import pandas as pd
import re, html, json, math
from collections import Counter
from pathlib import Path

DATA = Path('/app/benchmark/data.csv')
OUT = Path('/app/output/final_report.html')
df = pd.read_csv(DATA)

all_years = list(range(2015, 2026))
observed_years = sorted(df['year'].unique().tolist())
missing_years = [y for y in all_years if y not in observed_years]
type_order = ['MCQs', 'Short', 'Long']
colors = {'MCQs':'#2563eb','Short':'#0f9f6e','Long':'#f59e0b'}
soft_colors = {'MCQs':'#dbeafe','Short':'#d1fae5','Long':'#fef3c7'}
counts = pd.crosstab(df.year, df.type).reindex(index=observed_years, columns=type_order, fill_value=0)
counts['Total'] = counts[type_order].sum(axis=1)
counts['Observed Change'] = counts['Total'].diff()
counts['Observed Change %'] = counts['Total'].pct_change() * 100
overall_counts = df['type'].value_counts().reindex(type_order, fill_value=0)
overall_pct = overall_counts / len(df) * 100
avg_per_type = counts[type_order + ['Total']].mean()
median_total = counts['Total'].median()

# text preprocessing
stop = set('''the a an and or of in to is are was were be been being for from with without within into by on at as this that these those any all each every its it their there than then which what when where how why have has had do does did use used using called following given define describe explain write draw differentiate between note notes short long question questions answer option options true false name list state identify give find discuss represent represents'''.split())
stop |= set(['mcqs','paper','part','computer','science','class','hsc','biek','c','set','pair','two','three','one','four','also','different','difference','types','type','term','terms','example','examples','purpose','function'])
clean_text = ' '.join(df.question.astype(str).str.lower().str.replace('$',' ', regex=False))
words = re.findall(r"[a-z][a-z0-9+/#.-]*", clean_text)
words = [w.strip('.-') for w in words]
words = [w for w in words if len(w) > 2 and w not in stop and not w.isdigit()]
word_counts = Counter(words)
top_terms = word_counts.most_common(18)
bigrams = Counter(zip(words, words[1:]))
top_bigrams = [(' '.join(k), v) for k, v in bigrams.most_common(12)]

concepts = {
    'C/C++ programming':['loop','do-while','while','for','array','pointer','structure','function','operator','variable','constant','printf','scanf','syntax','program','programming','source','compiler','statement','statements','algorithm','flowchart','flow chart'],
    'Database systems':['database','dbms','sql','record','field','table','query','primary','key','file','data','entity','attribute','relation','relational'],
    'Operating systems':['operating','system','dos','windows','linux','process','memory','file'],
    'Object-oriented concepts':['object','class','inheritance','polymorphism','encapsulation','constructor','destructor','oop'],
    'Web/Internet':['internet','web','html','url','browser','email','e-mail','ftp','http','website','page','tag','network'],
    'Data structures':['stack','queue','linked','list','tree','graph','array'],
    'Logic & number systems':['binary','decimal','hexadecimal','logic','boolean','gate','truth'],
}
question_norm = df.question.astype(str).str.lower().str.replace('$',' ', regex=False)
concept_rows = []
concept_year_counts = {}
concept_type_counts = {}
for label, terms in concepts.items():
    pattern = re.compile(r'\b(?:' + '|'.join(re.escape(t) for t in terms) + r')\b')
    hit = question_norm.str.contains(pattern)
    mentions = sum(len(pattern.findall(q)) for q in question_norm)
    concept_rows.append((label, int(hit.sum()), mentions, hit.sum()/len(df)*100))
    concept_year_counts[label] = df.assign(hit=hit).groupby('year').hit.sum().reindex(observed_years, fill_value=0).astype(int).to_dict()
    concept_type_counts[label] = df.assign(hit=hit).groupby('type').hit.sum().reindex(type_order, fill_value=0).astype(int).to_dict()
concept_rows.sort(key=lambda x: x[1], reverse=True)

# SVG helpers
def svg_line_chart(series_map, years, width=920, height=360, title=None, y_label='Questions'):
    ml, mr, mt, mb = 58, 24, 30, 58
    plot_w, plot_h = width-ml-mr, height-mt-mb
    vals = [v for s in series_map.values() for v in s.values() if v is not None]
    ymax = max(vals) if vals else 1
    ymax = math.ceil(ymax/5)*5 or 5
    def x(year): return ml + (year-years[0])/(years[-1]-years[0])*plot_w
    def y(val): return mt + (ymax-val)/ymax*plot_h
    out = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Line chart" class="chart">']
    out.append('<rect width="100%" height="100%" rx="14" fill="#ffffff"/>')
    for tick in range(0, ymax+1, max(1, ymax//5)):
        yy=y(tick)
        out.append(f'<line x1="{ml}" y1="{yy:.1f}" x2="{width-mr}" y2="{yy:.1f}" stroke="#e5e7eb"/>')
        out.append(f'<text x="{ml-10}" y="{yy+4:.1f}" text-anchor="end" font-size="12" fill="#64748b">{tick}</text>')
    for yr in years:
        xx=x(yr)
        out.append(f'<text x="{xx:.1f}" y="{height-24}" text-anchor="middle" font-size="12" fill="#475569">{yr}</text>')
    for name, values in series_map.items():
        pts=[]
        for yr in years:
            val=values.get(yr)
            if val is None:
                if pts:
                    out.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{colors.get(name, "#111827")}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>')
                    pts=[]
                continue
            pts.append(f'{x(yr):.1f},{y(val):.1f}')
        if pts:
            out.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="{colors.get(name, "#111827")}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>')
        for yr in years:
            val=values.get(yr)
            if val is None: continue
            out.append(f'<circle cx="{x(yr):.1f}" cy="{y(val):.1f}" r="4.5" fill="{colors.get(name, "#111827")}" stroke="#fff" stroke-width="2"><title>{name} {yr}: {val}</title></circle>')
    # missing year marker
    for yr in missing_years:
        xx=x(yr)
        out.append(f'<line x1="{xx:.1f}" y1="{mt}" x2="{xx:.1f}" y2="{height-mb}" stroke="#ef4444" stroke-dasharray="5 5"/>')
        out.append(f'<text x="{xx+6:.1f}" y="{mt+14}" font-size="11" fill="#ef4444">missing</text>')
    out.append(f'<text x="{ml}" y="20" font-size="13" fill="#64748b">{html.escape(y_label)}</text>')
    out.append('</svg>')
    return ''.join(out)

def svg_stacked_counts(years, width=920, height=360):
    ml, mr, mt, mb = 58, 24, 28, 58
    plot_w, plot_h = width-ml-mr, height-mt-mb
    ymax = 40
    bar_gap = 12
    bar_w = (plot_w - bar_gap*(len(years)-1))/len(years)
    def y(val): return mt + (ymax-val)/ymax*plot_h
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Stacked bar chart" class="chart">','<rect width="100%" height="100%" rx="14" fill="#ffffff"/>']
    for tick in range(0, ymax+1, 10):
        yy=y(tick); out.append(f'<line x1="{ml}" y1="{yy:.1f}" x2="{width-mr}" y2="{yy:.1f}" stroke="#e5e7eb"/><text x="{ml-10}" y="{yy+4:.1f}" text-anchor="end" font-size="12" fill="#64748b">{tick}</text>')
    for i, yr in enumerate(years):
        x=ml+i*(bar_w+bar_gap)
        out.append(f'<text x="{x+bar_w/2:.1f}" y="{height-24}" text-anchor="middle" font-size="12" fill="#475569">{yr}</text>')
        if yr not in observed_years:
            out.append(f'<rect x="{x:.1f}" y="{mt}" width="{bar_w:.1f}" height="{plot_h}" fill="#fee2e2" opacity="0.7"/><text x="{x+bar_w/2:.1f}" y="{mt+plot_h/2:.1f}" text-anchor="middle" font-size="11" fill="#991b1b" transform="rotate(-90 {x+bar_w/2:.1f} {mt+plot_h/2:.1f})">No data</text>')
            continue
        base=0
        for t in type_order:
            val=int(counts.loc[yr,t])
            yy=y(base+val); hh=y(base)-yy
            out.append(f'<rect x="{x:.1f}" y="{yy:.1f}" width="{bar_w:.1f}" height="{hh:.1f}" fill="{colors[t]}"><title>{yr} {t}: {val}</title></rect>')
            if hh>18: out.append(f'<text x="{x+bar_w/2:.1f}" y="{yy+hh/2+4:.1f}" text-anchor="middle" font-size="11" fill="#fff">{val}</text>')
            base += val
    out.append('</svg>')
    return ''.join(out)

def svg_100pct(years, width=920, height=300):
    ml, mr, mt, mb = 58, 24, 28, 58
    plot_w, plot_h = width-ml-mr, height-mt-mb
    bar_gap = 12
    bar_w = (plot_w - bar_gap*(len(years)-1))/len(years)
    def y(p): return mt + (100-p)/100*plot_h
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="100 percent stacked bar chart" class="chart">','<rect width="100%" height="100%" rx="14" fill="#ffffff"/>']
    for tick in [0,25,50,75,100]:
        yy=y(tick); out.append(f'<line x1="{ml}" y1="{yy:.1f}" x2="{width-mr}" y2="{yy:.1f}" stroke="#e5e7eb"/><text x="{ml-10}" y="{yy+4:.1f}" text-anchor="end" font-size="12" fill="#64748b">{tick}%</text>')
    for i, yr in enumerate(years):
        x=ml+i*(bar_w+bar_gap)
        out.append(f'<text x="{x+bar_w/2:.1f}" y="{height-24}" text-anchor="middle" font-size="12" fill="#475569">{yr}</text>')
        if yr not in observed_years:
            out.append(f'<rect x="{x:.1f}" y="{mt}" width="{bar_w:.1f}" height="{plot_h}" fill="#fee2e2" opacity="0.7"/>')
            continue
        base=0; total=counts.loc[yr,'Total']
        for t in type_order:
            pct=counts.loc[yr,t]/total*100
            yy=y(base+pct); hh=y(base)-yy
            out.append(f'<rect x="{x:.1f}" y="{yy:.1f}" width="{bar_w:.1f}" height="{hh:.1f}" fill="{colors[t]}"><title>{yr} {t}: {pct:.1f}%</title></rect>')
            if hh>20: out.append(f'<text x="{x+bar_w/2:.1f}" y="{yy+hh/2+4:.1f}" text-anchor="middle" font-size="10" fill="#fff">{pct:.0f}%</text>')
            base += pct
    out.append('</svg>')
    return ''.join(out)

def svg_horizontal_bars(items, width=920, height=430, title=''):
    ml, mr, mt, mb = 160, 34, 22, 25
    plot_w, plot_h = width-ml-mr, height-mt-mb
    maxv=max(v for _,v in items) or 1
    row_h=plot_h/len(items)
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Horizontal bar chart" class="chart">','<rect width="100%" height="100%" rx="14" fill="#ffffff"/>']
    for i,(label,val) in enumerate(items):
        y=mt+i*row_h+row_h*0.18; h=row_h*0.64; w=val/maxv*plot_w
        out.append(f'<text x="{ml-12}" y="{y+h/2+4:.1f}" text-anchor="end" font-size="12" fill="#334155">{html.escape(label)}</text>')
        out.append(f'<rect x="{ml}" y="{y:.1f}" width="{w:.1f}" height="{h:.1f}" rx="5" fill="#2563eb"><title>{html.escape(label)}: {val}</title></rect>')
        out.append(f'<text x="{ml+w+8:.1f}" y="{y+h/2+4:.1f}" font-size="12" fill="#475569">{val}</text>')
    out.append('</svg>')
    return ''.join(out)

def svg_concept_bars(rows, width=920, height=310):
    items=[(r[0], r[1]) for r in rows]
    return svg_horizontal_bars(items, width, height)

def svg_heatmap(concept_year_counts, width=920, height=360):
    labels=list(concept_year_counts.keys())
    years=observed_years
    ml, mr, mt, mb = 170, 20, 34, 45
    cell_w=(width-ml-mr)/len(years)
    cell_h=(height-mt-mb)/len(labels)
    maxv=max(v for d in concept_year_counts.values() for v in d.values()) or 1
    def col(v):
        # interpolate from very light blue to dark blue
        a=v/maxv
        r=int(239+(37-239)*a); g=int(246+(99-246)*a); b=int(255+(235-255)*a)
        return f'rgb({r},{g},{b})'
    out=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Topic-year heatmap" class="chart">','<rect width="100%" height="100%" rx="14" fill="#ffffff"/>']
    for j,yr in enumerate(years):
        out.append(f'<text x="{ml+j*cell_w+cell_w/2:.1f}" y="22" text-anchor="middle" font-size="12" fill="#475569">{yr}</text>')
    for i,label in enumerate(labels):
        y=mt+i*cell_h
        out.append(f'<text x="{ml-10}" y="{y+cell_h/2+4:.1f}" text-anchor="end" font-size="12" fill="#334155">{html.escape(label)}</text>')
        for j,yr in enumerate(years):
            v=concept_year_counts[label].get(yr,0)
            x=ml+j*cell_w
            out.append(f'<rect x="{x+1:.1f}" y="{y+1:.1f}" width="{cell_w-2:.1f}" height="{cell_h-2:.1f}" rx="5" fill="{col(v)}"><title>{html.escape(label)} {yr}: {v} question rows</title></rect>')
            out.append(f'<text x="{x+cell_w/2:.1f}" y="{y+cell_h/2+4:.1f}" text-anchor="middle" font-size="11" fill="{"#fff" if v/maxv > .55 else "#1e293b"}">{v}</text>')
    out.append('</svg>')
    return ''.join(out)

