body {{ margin:0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color:var(--ink); background:var(--bg); line-height:1.55; }}
header {{ background:linear-gradient(135deg,#0f172a 0%,#1e3a8a 62%,#0f766e 100%); color:#fff; padding:54px 7vw 44px; }}
header h1 {{ margin:0 0 12px; font-size:clamp(28px,4vw,48px); line-height:1.08; letter-spacing:-.03em; max-width:1100px; }}
header p {{ margin:0; max-width:980px; color:#dbeafe; font-size:18px; }}
main {{ max-width:1180px; margin:0 auto; padding:30px 22px 70px; }}
section {{ background:var(--card); border:1px solid var(--line); border-radius:18px; padding:26px; margin:22px 0; box-shadow:0 10px 28px rgba(15,23,42,.05); }}
h2 {{ margin:0 0 14px; font-size:26px; letter-spacing:-.02em; }}
h3 {{ margin:24px 0 10px; font-size:18px; }}
p {{ margin:10px 0; }}
.kpi-grid {{ display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; margin-top:-30px; position:relative; }}
.kpi {{ background:#fff; border:1px solid var(--line); border-radius:16px; padding:18px; box-shadow:0 12px 28px rgba(15,23,42,.10); }}
.kpi .label {{ color:var(--muted); font-size:13px; text-transform:uppercase; letter-spacing:.08em; }}
.kpi .value {{ font-size:32px; font-weight:800; margin-top:4px; }}
.kpi .note {{ color:var(--muted); font-size:13px; }}
.grid-2 {{ display:grid; grid-template-columns:1fr 1fr; gap:18px; align-items:start; }}
.chart-wrap {{ border:1px solid var(--line); border-radius:16px; background:#fff; padding:10px; margin:16px 0; overflow-x:auto; }}
.chart {{ width:100%; min-width:760px; display:block; }}
.legend {{ display:flex; flex-wrap:wrap; gap:12px 18px; margin:8px 0 4px; color:#475569; font-size:14px; }}
.legend span::before {{ content:""; display:inline-block; width:12px; height:12px; border-radius:3px; margin-right:7px; vertical-align:-1px; background:var(--c); }}
table {{ width:100%; border-collapse:collapse; margin:14px 0; font-size:14px; }}
th,td {{ padding:10px 12px; border-bottom:1px solid var(--line); text-align:left; vertical-align:top; }}
th {{ background:#f1f5f9; color:#334155; font-weight:700; }}
tr.missing td {{ color:#991b1b; background:#fef2f2; }}
.callout {{ border-left:5px solid var(--blue); background:#eff6ff; padding:14px 16px; border-radius:12px; margin:16px 0; }}
.warning {{ border-left-color:var(--red); background:#fef2f2; }}
.good {{ border-left-color:var(--green); background:#ecfdf5; }}
.chips {{ display:flex; gap:10px; flex-wrap:wrap; margin:12px 0; }}
.chip {{ display:inline-flex; gap:7px; align-items:center; border:1px solid #bfdbfe; color:#1e3a8a; background:#eff6ff; padding:7px 10px; border-radius:999px; font-size:13px; }}
.chip.alt {{ border-color:#bbf7d0; color:#14532d; background:#f0fdf4; }}
ul {{ padding-left:22px; }}
li {{ margin:8px 0; }}
.small {{ color:var(--muted); font-size:13px; }}
.footer {{ color:#64748b; text-align:center; padding:16px; font-size:13px; }}
@media (max-width:900px) {{ .kpi-grid,.grid-2 {{ grid-template-columns:1fr; }} header {{ padding-left:24px; padding-right:24px; }} section {{ padding:20px; }} }}
</style>
